import{c as e,Z as l,Q as o,j as t,m as r,o as s}from"./chunks/framework.DOi4mjdC.js";const b=JSON.parse('{"title":"关雎","description":"","frontmatter":{"title":"关雎","author":"佚名","dynasty":"先秦"},"headers":[],"relativePath":"books/shici/shijing/1.md","filePath":"books/shici/shijing/1.md"}'),n={name:"books/shici/shijing/1.md"};function h(c,a,d,p,u,_){const i=l("PoemNav");return o(),t("div",null,[a[0]||(a[0]=r('<h1 id="关雎" tabindex="-1">关雎 <a class="header-anchor" href="#关雎" aria-label="Permalink to &quot;关雎&quot;">​</a></h1><p><strong>《诗经·周南》</strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>关关雎鸠，在河之洲。窈窕淑女，君子好逑。 参差荇菜，左右流之。窈窕淑女，寤寐求之。 求之不得，寤寐思服。悠哉悠哉，辗转反侧。 参差荇菜，左右采之。窈窕淑女，琴瑟友之。 参差荇菜，左右芼之。窈窕淑女，钟鼓乐之。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>关关：鸟鸣声</li><li>雎鸠：一种水鸟，传说雌雄形影不离</li><li>洲：水中的陆地</li><li>窈窕：美好的样子</li><li>淑：善良、美好</li><li>逑：配偶</li><li>参差：长短不齐的样子</li><li>荇菜：一种水生植物，可食用</li><li>流：求取，捞取</li><li>寤寐：醒时和睡时，指日夜</li><li>思服：思念</li><li>悠：忧思的样子</li><li>辗转反侧：翻来覆去，难以入眠</li><li>友：亲近</li><li>芼：择取</li><li>乐：取悦</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>关关和鸣的雎鸠，相伴在河中的小洲。那美丽贤淑的女子，是君子的好配偶。 参差不齐的荇菜，从左到右去捞它。那美丽贤淑的女子，醒来睡去都想追求她。 追求却没法得到，白天黑夜便总思念她。长长的思念啊，叫人翻来覆去难入眠。 参差不齐的荇菜，从左到右去采它。那美丽贤淑的女子，弹琴鼓瑟来亲近她。 参差不齐的荇菜，从左到右去拔它。那美丽贤淑的女子，敲钟打鼓来取悦她。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>《关雎》是《诗经》的首篇，是一首描写男女恋爱的情歌。此诗在艺术上巧妙地采用了&quot;兴&quot;的表现手法，先以物起兴，然后再以雎鸠之挚而有别，兴淑女应配君子。全诗语言优美，善于运用双声叠韵和重章叠词，增强了诗歌的音韵美和写人状物、拟声传情的生动性。</p><hr><h2 id="关于《诗经》" tabindex="-1">关于《诗经》 <a class="header-anchor" href="#关于《诗经》" aria-label="Permalink to &quot;关于《诗经》&quot;">​</a></h2><blockquote><p>《诗经》是中国古代诗歌开端，最早的一部诗歌总集，收集了西周初年至春秋中叶的诗歌305篇，又称“诗三百”。作者多不可考，相传为孔子编订。</p><p><a href="/books/shici/shijing.html">查看诗经详情 →</a></p></blockquote>',13)),s(i)])}const q=e(n,[["render",h]]);export{b as __pageData,q as default};
